def patch(path, block):
    p = Path(path)
    s = p.read_text(encoding='utf-8')
    if 'data-digiy-loc-example="1"' in s:
        print(path, 'already patched')
        return False
    if '</head>' not in s or '</main><footer' not in s:
        raise SystemExit(f'{path}: expected anchors not found')
    s = s.replace('</head>', STYLE + '</head>', 1)
    s = s.replace('</main><footer', block + '</main><footer', 1)
    p.write_text(s, encoding='utf-8')
    print(path, 'patched')
    return True

changed = []
if patch('miami.html', MIAMI): changed.append('miami.html')
if patch('paris.html', PARIS): changed.append('paris.html')
print('changed:', changed)
